{"cards": [{"node_code": "N_3f7c596abf2aeaca", "definition": "研究铁路编组站的站场布置、改编作业流程、驼峰调车技术、通过能力计算及车流组织的管理工程内容。", "boundary": "本节点聚焦于“编组站”这一特定类型车站，核心功能是列车解体与编组。边界在于区分“编组站”与“区段站”（区段站侧重机车整备与列车技术检查，改编量较小）、“货运站”（侧重货物装卸而非车辆编组）。若内容涉及枢纽内编组站与其他站的协调，归铁路枢纽；若涉及具体调车机车技术，归车辆工程。", "includes": ["编组站站场配置（到达场、调车场、出发场）及驼峰/非驼峰调车作业组织", "编组站通过能力、改编能力计算及车流径路规划", "编组站作业计划编制、调车作业标准及安全管理"], "excludes": ["区段站的机车整备、列车技术检查等作业组织（归区段站）", "货物装卸、仓储及集装箱堆场管理（归货运站、集装箱站）", "编组站土建结构设计、信号设备硬件制造（归铁路工程/通信信号）"], "sibling_distinctions": [{"other_code": "N_ca1d106c7593f5c5", "rule": "区分依据为功能侧重：编组站以车辆改编（解体、编组）为核心，作业量大、站场复杂；区段站以机车整备、列车技术检查及少量改编为主，服务于区段列车运行。"}, {"other_code": "N_38884d34b84a7624", "rule": "区分依据为作业对象：编组站处理“车辆/列车”的编组与解体；货运站处理“货物”的装卸、交接及仓储。"}], "cross_boundary_rule": "若内容涉及“编组站自动化”，侧重调车作业流程优化与算法归本节点；侧重调车机车控制归车辆工程；侧重信号联锁归通信信号。"}, {"node_code": "N_38884d34b84a7624", "definition": "研究铁路货运站及集装箱站的货物装卸、仓储、交接作业组织、站场配置及集装箱管理的管理工程内容。", "boundary": "本节点聚焦于“货物”在车站内的流转与管理，包括普通货物与集装箱。边界在于区分“货运站”与“编组站”（编组站侧重车辆编组，货运站侧重货物装卸）、“货运站”与“客运站”（服务对象不同）。若内容涉及集装箱多式联运整体协调，可关联综合运输，但站内作业归本节点。", "includes": ["货运站、集装箱站的站场布置（货场、仓库、堆场、装卸线）及作业流程", "货物装卸、搬运、仓储、交接及集装箱堆存、拆装箱管理", "货运站通过能力计算、货运计划编制及货运安全管理"], "excludes": ["车辆编组、解体作业组织（归编组站）", "旅客服务、候车室管理（归客运站）", "货物本身的包装技术、运输途中监控（归货物运输技术或物流）"], "sibling_distinctions": [{"other_code": "N_3f7c596abf2aeaca", "rule": "区分依据为作业对象：货运站侧重“货物”的装卸与仓储；编组站侧重“车辆”的编组与解体。"}, {"other_code": "N_9a7bb4330b13cf75", "rule": "区分依据为服务对象：货运站服务“货物”运输；客运站服务“旅客”运输。"}], "cross_boundary_rule": "若内容涉及“集装箱多式联运”，侧重铁路站内集装箱作业归本节点；侧重公铁/铁水联运整体协调归综合运输或相关联运节点。"}, {"node_code": "N_9a7bb4330b13cf75", "definition": "研究铁路客运站的旅客服务、候车组织、售票管理、站场配置及客运作业流程的管理工程内容。", "boundary": "本节点聚焦于“旅客”在车站内的服务与组织。边界在于区分“客运站”与“货运站”（服务对象不同）、“客运站”与“编组站”（客运站侧重旅客流线与服务，编组站侧重车辆作业）。若内容涉及高铁站综合开发，侧重运输组织归本节点，侧重商业运营归相关商业节点。", "includes": ["客运站（含高铁站）的站场布置、旅客流线设计、候车室及站台管理", "旅客售票、检票、候车、乘降组织及客运服务标准", "客运站通过能力计算、客运计划编制及客运安全管理"], "excludes": ["货物装卸、仓储及集装箱管理（归货运站、集装箱站）", "车辆编组、解体作业组织（归编组站）", "车站建筑结构设计、非运输类商业经营（归铁路工程/商业）"], "sibling_distinctions": [{"other_code": "N_38884d34b84a7624", "rule": "区分依据为服务对象：客运站侧重“旅客”服务与流线；货运站侧重“货物”装卸与仓储。"}, {"other_code": "N_3f7c596abf2aeaca", "rule": "区分依据为功能侧重：客运站侧重旅客乘降与服务；编组站侧重车辆编组与解体。"}], "cross_boundary_rule": "若内容涉及“高铁站综合开发”，侧重旅客运输组织与服务归本节点；侧重站房商业运营归相关商业或管理节点。"}]}
